script/testnet/D14Testnet.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Script, console2} from "forge-std/Script.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";

import {HyperVault} from "../../src/HyperVault.sol";
import {VaultPolicy} from "../../src/VaultPolicy.sol";
import {InitParams} from "../../src/VaultTypes.sol";
import {ICoreDepositWallet} from "../../src/hypercore/HyperCore.sol";
import {Addresses} from "../Deploy.s.sol";

/// @notice D14 (round 2, WP5 step 4), step 2: launches the HyperCore test vault on HyperEVM testnet (chain 998) from
///         the implementations that `script/Deploy.s.sol:DeployFactory` deployed (read from deployments/testnet.json).
///
/// Why a standalone clone and not factory.create(): a factory vault launched with an agent waits AGENT_WARMUP (24 h,
/// `agentActiveAt`) before the agent's first order (VaultLogic.placeOrder reverts AgentWarmingUp), and a factory vault
/// launched without one can only get it through the owner timelock (queue + execute, at least MIN_TIMELOCK = 1 day).
/// VaultGovernance.initialize sets agentActiveAt only when `factory != 0`, so a standalone clone of the SAME
/// implementation with the agent in InitParams has agentActiveAt = 0 and the agent may trade at once. Everything D14
/// checks is the same code in both: placeOrder (IOC only, cloid, turnover / order rate, checkRisk first, mode guard),
/// pinAccountMode / _pinMode (CoreWriter action 16) and the precompile reads. Only the role lookup differs: a
/// standalone vault's guardian and sentinel are the one `guardian` field (here the owner).
///
/// No USDC seed and no HYPE value: on testnet an EVM -> Core deposit to an address with no HyperCore MAINNET state is
/// dropped silently, and a fresh contract never has mainnet state. The vault's Core account is opened and funded by a
/// HyperCore spot send from the owner's wallet (docs/fix-round/TESTNET-D14.md, step 3).
///
/// Signing: only `--account <keystore>` (or `--interactive`); the broadcaster becomes owner, manager, guardian and
/// fee recipient. Small blocks are enough (two EIP-1167 clones and two initializers).
///
/// Env:
///   AGENT          required: the agent wallet (keystore d14-agent); recorded at initialization (nothing sent to Core)
///   D14_ASSET      perp index, default 3 (BTC on HL testnet; mainnet BTC is 0). Allowed in the vault's policy.
///   D14_DEPLOYMENT default deployments/testnet.json (written by DeployFactory)
///   D14_RECORD     default deployments/testnet-d14.json (written here)
/// Risk parameters: the production defaults of script/Deploy.s.sol:LaunchVault (3x, 5% daily, 15% drawdown, 1%
/// slippage band, 250k per order, 7 day epoch, 20% NAV move, 3% flatten cap); agent limits: the VaultPolicy defaults
/// (20x NAV turnover a day, 120 orders an hour).
contract D14Launch is Script {
    function run() external returns (HyperVault vault, VaultPolicy policy) {
        require(block.chainid == 998, "D14Launch: HyperEVM testnet (998) only");
        address me = msg.sender;
        address agent = vm.envAddress("AGENT");
        require(agent != address(0) && agent != me, "AGENT must be a separate wallet");
        uint32 asset = uint32(vm.envOr("D14_ASSET", uint256(3)));

        string memory dep = vm.readFile(vm.envOr("D14_DEPLOYMENT", string("deployments/testnet.json")));
        address vaultImpl = vm.parseJsonAddress(dep, ".vaultImplementation");
        address policyImpl = vm.parseJsonAddress(dep, ".policyImplementation");
        require(vaultImpl.code.length > 0 && policyImpl.code.length > 0, "implementations not deployed");

        uint32[] memory assets = new uint32[](1);
        assets[0] = asset;
        VaultPolicy.RiskConfig memory risk = VaultPolicy.RiskConfig({
            maxLeverageBps: 30_000,
            maxDailyLossBps: 500,
            maxDrawdownBps: 1_500,
            maxSlippageBps: 100,
            maxOrderNotional: 250_000e6,
            maxEpochDuration: 7 days,
            maxNavMoveBps: 2_000,
            maxFlattenSlippageBps: 300
        });

        vm.startBroadcast();
        policy = VaultPolicy(Clones.clone(policyImpl));
        policy.initialize(me, risk, assets, 2 days, address(0));
        vault = HyperVault(Clones.clone(vaultImpl));
        vault.initialize(
            InitParams({
                asset: IERC20(Addresses.usdc()),
                name: "D14 Testnet Vault",
                symbol: "dpD14",
                owner: me,
                manager: me,
                guardian: me,
                feeRecipient: me,
                managementFeeBps: 200,
                performanceFeeBps: 2_000,
                timelockDelay: 2 days,
                depositCap: 0,
                policy: policy,
                coreDepositWallet: ICoreDepositWallet(Addresses.cdw()),
                factory: address(0),
                protocolShareBps: 0,
                baseShareBps: 0,
                hosted: false,
                agent: agent,
                operator: address(0),
                seedUsdc: 0
            })
        );
        vm.stopBroadcast();

        require(vault.agent() == agent, "agent not recorded");
        require(vault.agentActiveAt() == 0, "agent warm-up set (not a standalone vault?)");
        require(vault.modePinnedAt() == 0, "pinned before the Core account exists");
        require(vault.orderPath() == 1, "not an HL-PROXY implementation");
        require(policy.isAssetAllowed(asset), "asset not allowed");

        console2.log("VaultPolicy       ", address(policy));
        console2.log("HyperVault        ", address(vault));
        console2.log("agent             ", agent);
        console2.log("agentActiveAt      0 (no warm-up)");
        console2.log("asset             ", uint256(asset));

        string memory j = "d14";
        vm.serializeUint(j, "chainId", block.chainid);
        vm.serializeUint(j, "block", block.number);
        vm.serializeAddress(j, "vault", address(vault));
        vm.serializeAddress(j, "policy", address(policy));
        vm.serializeAddress(j, "owner", me);
        vm.serializeAddress(j, "agent", agent);
        vm.serializeAddress(j, "vaultImplementation", vaultImpl);
        string memory out = vm.serializeUint(j, "asset", asset);
        string memory path = vm.envOr("D14_RECORD", string("deployments/testnet-d14.json"));
        vm.writeJson(out, path);
        console2.log("Written", path);
        console2.log("Next: open the vault's Core account with a HyperCore spot send to it (TESTNET-D14.md step 3).");
    }
}

src/HyperVault.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {Ownable2StepUpgradeable, OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

import {ICoreDepositWallet} from "./hypercore/HyperCore.sol";
import {VaultPolicy} from "./VaultPolicy.sol";
import {VaultLogic} from "./VaultLogic.sol";
import {VaultGovernance} from "./VaultGovernance.sol";
import {VaultMath} from "./VaultMath.sol";
import {
    BRIDGE_SETTLE_BLOCKS as BRIDGE_SETTLE_BLOCKS_,
    BreachReason,
    GRACE_PERIOD as GRACE_PERIOD_,
    IHyperVaultErrors,
    IHyperVaultEvents,
    IVaultFactory,
    InitParams,
    LEVERAGE_CLEAR_COOLDOWN as LEVERAGE_CLEAR_COOLDOWN_,
    MAX_BRIDGE_WAIT_BLOCKS as MAX_BRIDGE_WAIT_BLOCKS_,
    MAX_UNLANDED_BLOCKS as MAX_UNLANDED_BLOCKS_,
    MIN_DEPOSIT as MIN_DEPOSIT_,
    RESUME_COOLDOWN as RESUME_COOLDOWN_,
    INSIDER_MIN_EPOCH_AGE as INSIDER_MIN_EPOCH_AGE_,
    MIN_BRIDGE as MIN_BRIDGE_,
    VaultStorage
} from "./VaultTypes.sol";

/// @title HyperVault
/// @notice Non custodial USDC vault on HyperEVM that trades Hyperliquid perps from its own HyperCore account.
///
/// Flow
///  - Depositors use async requests (ERC-7540 style): requestDeposit / requestRedeem, then claim after the
///    epoch settles. Synchronous ERC-4626 entrypoints do not exist because NAV lives partly on HyperCore.
///  - The vault contract address IS the HyperCore trading account. Funds never leave the contract's control.
///  - Execution: onchain orders via CoreWriter only, every order checked against VaultPolicy. The manager or the
///    platform agent (the EVM wallet the factory bound to this vault, driven by the DojiPad executor) calls
///    placeOrder; the agent is never approved as a HyperCore API wallet (HL-PROXY), so it cannot move funds,
///    trade spot or other dexes, or change the account mode. The account is pinned to the Standard mode.
///  - Anyone can call checkRisk(). Every loss is measured on the share price, so deposits, redemptions and fee
///    mints never move it (R-01). A risk breach derisks, it does not shut the vault: reduce only, agent kept.
///    Leverage clears by itself (clearLeverageBreach, anyone, once every limit is met), daily loss at the next UTC
///    day, drawdown when the owner calls resume(). The guardian / sentinel / owner full stop (triggerBreach) and
///    emergency revoke the agent; the cold guardian clears those (or the owner after a timelock from the breach).
///    Only the cold guardian ends an emergency.
///  - If an epoch with pending redemptions is overdue, anyone can trigger emergency mode; the unwind (flatten,
///    bridge back, settle) is for the owner, manager, operator, sentinel and guardian only. Emergency settlements
///    only pay exits: a partial fill pro rata to the liquidity on hand, the unpaid shares returned to the
///    redeemers (who may request again). Depositors always request redemptions and claim as normal.
///  - An optional treasury operator (the platform keeper by default) may settle, bridge and move USDC between spot
///    and perp, nothing else.
///
/// Layout: this contract holds the ERC-20 shares, ownership, the read-only surface and thin entry points. The
/// logic lives in two linked libraries (VaultLogic, VaultGovernance) that run by delegatecall on the single
/// `VaultStorage` struct below. Read-only helpers for integrators live in HyperVaultLens.
/// Deployment: EIP-1167 clone of a fixed implementation, initialized once by the factory. Not upgradeable.
contract HyperVault is Initializable, ERC20Upgradeable, Ownable2StepUpgradeable, IHyperVaultEvents, IHyperVaultErrors {
    using SafeERC20 for IERC20;
    using VaultMath for VaultStorage;

    VaultStorage internal $;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(InitParams calldata p) external payable initializer {
        __ERC20_init(p.name, p.symbol);
        __Ownable_init(p.owner);
        __Ownable2Step_init();
        VaultGovernance.initialize($, p, msg.value);
    }

    // ==================================================================
    // Roles. Factory vaults read the guardian (cold) and the sentinel (hot) from the factory, so the platform can
    // rotate them for every vault at once; standalone vaults have one fixed guardian that is also the sentinel.
    // ==================================================================
    function guardian() public view returns (address) {
        return $.factory != address(0) ? IVaultFactory($.factory).guardian() : $.guardian;
    }

    function sentinel() public view returns (address) {
        return $.factory != address(0) ? IVaultFactory($.factory).sentinel() : $.guardian;
    }

    modifier onlySelf() {
        if (msg.sender != address(this)) revert Unauthorized();
        _;
    }

    // ==================================================================
    // ERC-4626 style accounting (shares only; no sync deposit/mint/withdraw/redeem)
    // ==================================================================
    function asset() external view returns (address) {
        return address($.asset);
    }

    function decimals() public pure override returns (uint8) {
        return 12;
    }

    /// @notice Net asset value in USDC (6 decimals). Inside a bridge window it is the pre-bridge snapshot.
    function totalAssets() public view returns (uint256) {
        return $.totalAssets();
    }

    function convertToShares(uint256 assets) external view returns (uint256) {
        return VaultMath.toShares(assets, totalAssets(), totalSupply(), Math.Rounding.Floor);
    }

    function convertToAssets(uint256 shares) external view returns (uint256) {
        return VaultMath.toAssets(shares, totalAssets(), totalSupply(), Math.Rounding.Floor);
    }

    /// @dev Rounding follows the ERC-4626 reference. Pending fees are not included: HyperVaultLens.preview* are.
    function previewDeposit(uint256 assets) external view returns (uint256) {
        return VaultMath.toShares(assets, totalAssets(), totalSupply(), Math.Rounding.Floor);
    }

    function previewMint(uint256 shares) external view returns (uint256) {
        return VaultMath.toAssets(shares, totalAssets(), totalSupply(), Math.Rounding.Ceil);
    }

    function previewWithdraw(uint256 assets) external view returns (uint256) {
        return VaultMath.toShares(assets, totalAssets(), totalSupply(), Math.Rounding.Ceil);
    }

    function previewRedeem(uint256 shares) external view returns (uint256) {
        return VaultMath.toAssets(shares, totalAssets(), totalSupply(), Math.Rounding.Floor);
    }

    function idleAssets() external view returns (uint256) {
        return $.idleAssets();
    }

    function coreEquity() external view returns (uint256) {
        return VaultMath.coreEquity();
    }

    /// @notice In flight or late (unlanded, at most MAX_UNLANDED_BLOCKS): settle and treasury actions wait.
    function bridgePending() external view returns (bool) {
        return $.bridgePending();
    }

    /// @notice A transfer is late past MAX_UNLANDED_BLOCKS and the NAV reads short by it: settles and bridges wait
    ///         (at most UNRESOLVED_WAIT_BLOCKS) until it lands or the guardian writes it off.
    function bridgeUnresolved() external view returns (bool) {
        return $.bridgeUnresolved();
    }

    function bridgeInFlight() external view returns (bool) {
        return $.bridgeInFlight();
    }

    /// @notice Assets per one whole share (10 ** decimals()).
    function sharePrice() external view returns (uint256) {
        return $.sharePrice();
    }

    /// @notice Expected fill of the pending redemptions if an exit-only settle ran now (10_000 = in full).
    function emergencyFillBps() external view returns (uint256) {
        return $.emergencyFillBps();
    }

    // ==================================================================
    // Depositor flow
    // ==================================================================
    function requestDeposit(uint256 assets, address controller) external returns (uint256) {
        return VaultLogic.requestDeposit($, assets, controller);
    }

    function requestRedeem(uint256 shares, address controller, address owner_) external returns (uint256) {
        return VaultLogic.requestRedeem($, shares, controller, owner_);
    }

    function cancelDepositRequest() external {
        VaultLogic.cancelDepositRequest($);
    }

    function cancelRedeemRequest() external {
        VaultLogic.cancelRedeemRequest($);
    }

    function claim(address controller) external {
        VaultLogic.claim($, controller);
    }

    // ==================================================================
    // Settlement, fees, hosting
    // ==================================================================
    /// @dev A vault that has never been checkpointed runs the risk check itself first, so the first settle does
    ///      not depend on a keeper (audit I2-04).
    function settle() external {
        if ($.checkpointAt == 0) VaultGovernance.checkRisk($);
        VaultLogic.settle($, guardian(), sentinel());
    }

    function accrueFees() external {
        VaultLogic.accrueFees($);
    }

    function leaveHosted() external {
        VaultLogic.leaveHosted($);
    }

    function lowerProtocolShare(uint16 newBps) external {
        VaultLogic.lowerProtocolShare($, newBps);
    }

    // ==================================================================
    // Bridging
    // ==================================================================
    function bridgeToCore(uint256 amount) external {
        VaultLogic.bridgeToCore($, amount);
    }

    function bridgeToEvm(uint256 amount) external {
        VaultLogic.bridgeToEvm($, amount, guardian(), sentinel());
    }

    /// @notice Anyone (the keeper): records that the latest bridge has landed, so the window can never reopen (R-02).
    function syncBridge() external {
        VaultLogic.syncBridge($);
    }

    function fundCoreGas() external payable {
        VaultLogic.fundCoreGas($, msg.value);
    }

    function moveUsd(uint256 amount, bool toPerp) external {
        VaultLogic.moveUsd($, amount, toPerp);
    }

    // ==================================================================
    // Trading
    // ==================================================================
    /// @notice Manager or platform agent. An order that adds risk runs the risk check first (HL-PROXY, the HL twin of
    ///         Gains GR2-KEY-01): when that check puts the vault in reduce only the order is not sent (OrderRefused)
    ///         and the breach stays recorded. In a breach that already exists such an order reverts, as before.
    function placeOrder(uint32 asset_, bool isBuy, uint64 limitPx, uint64 sz, bool reduceOnly, uint8 tif, uint128 cloid) external {
        bool trader = msg.sender == $.manager || (msg.sender == $.agent && $.agent != address(0));
        if (!reduceOnly && trader && !$.breached && !$.emergency) {
            VaultGovernance.checkRisk($);
            if ($.breached || $.emergency) {
                emit OrderRefused(asset_, cloid, msg.sender);
                return;
            }
        }
        VaultLogic.placeOrder($, asset_, isBuy, limitPx, sz, reduceOnly, tif, cloid);
    }

    function cancelOrder(uint32 asset_, uint64 oid) external {
        VaultLogic.cancelOrder($, asset_, oid, sentinel());
    }

    function flatten(uint32 asset_, uint256 slippageBps) external {
        VaultLogic.flatten($, asset_, slippageBps, guardian(), sentinel());
    }

    // ==================================================================
    // Agent
    // ==================================================================
    /// @notice Timelocked (queue + execute). Only the platform agent bound to this vault on the factory.
    function setAgent(address newAgent) external onlySelf {
        if ($.hardStop()) revert ReduceOnlyMode();
        VaultLogic.setAgent($, newAgent);
    }

    /// @notice HL-PROXY: re-pins the HyperCore account to the Standard mode (CoreWriter action 16, abstraction 1).
    ///         Vault roles at any time, anyone else once per MODE_PIN_INTERVAL. Replaces syncAgent(): there is no
    ///         HyperCore approval to send for the agent any more.
    function pinAccountMode() external {
        VaultLogic.pinAccountMode($, guardian(), sentinel());
    }

    /// @notice WP1: the agent's opened notional in the rolling 24 hours and its orders that add risk in the sliding hour,
    ///         against VaultPolicy.agentLimits().
    function agentFlow() external view returns (uint256 used, uint256 orders) {
        return VaultLogic.agentFlow($);
    }

    /// @notice Kept for ABI compatibility (executor, integrators): same as pinAccountMode(). It approves nothing on
    ///         HyperCore any more (HL-PROXY).
    function syncAgent() external {
        VaultLogic.pinAccountMode($, guardian(), sentinel());
    }

    /// @notice When the account mode was last pinned (0 = never).
    function modePinnedAt() external view returns (uint64) {
        return $.modePinnedAt;
    }

    /// @notice HL-PROXY marker for the executor: 1 = orders go through placeOrder (no HyperCore API wallet).
    function orderPath() external pure returns (uint256) {
        return 1;
    }

    /// @notice true while the precompiles show a balance layout the Standard account mode cannot produce.
    function accountModeSuspect() external view returns (bool) {
        return VaultMath.modeSuspect();
    }

    /// @notice Instant: owner, guardian, sentinel or the factory (when the agent is unregistered). A platform revoke
    ///         of a live agent (guardian, sentinel, factory) also holds deposits until the guardian clears
    ///         (HLR2-XA01): the revoked agent may have deflated the NAV, so no settle prices a deposit meanwhile.
    function revokeAgent() external {
        if (msg.sender != owner() && msg.sender != guardian() && msg.sender != sentinel() && msg.sender != $.factory) {
            revert Unauthorized();
        }
        if (msg.sender != owner() && $.agent != address(0) && !$.depositHold) {
            $.depositHold = true;
            emit DepositHold(true);
        }
        VaultLogic.revokeAgent($);
    }

    function depositHold() external view returns (bool) {
        return $.depositHold;
    }

    // ==================================================================
    // Risk, breach, emergency
    // ==================================================================
    function checkRisk() external returns (uint256 leverageBps, uint256 dailyLossBps, uint256 drawdownBps) {
        return VaultGovernance.checkRisk($);
    }

    function triggerBreach() external {
        VaultGovernance.triggerBreach($, guardian(), sentinel());
    }

    function triggerEmergency() external {
        VaultGovernance.triggerEmergency($, guardian());
    }

    function clearBreach() external {
        VaultGovernance.clearBreach($, guardian());
    }

    /// @notice Guardian: writes off the late transfer that holds settles (HLR2-A02 / A08).
    function writeOffBridge() external {
        VaultGovernance.writeOffBridge($, guardian());
    }

    /// @notice Anyone: lifts a leverage breach once every limit is met again (after LEVERAGE_CLEAR_COOLDOWN).
    function clearLeverageBreach() external {
        VaultGovernance.clearLeverageBreach($);
    }

    /// @notice Owner: ends a drawdown breach and restarts the peak from the current share price.
    function resume() external {
        VaultGovernance.resume($);
    }

    // ==================================================================
    // Treasury operator
    // ==================================================================
    /// @notice Owner: grants the operator (settle, bridges, moveUsd only); zero removes it.
    function setOperator(address operator_) external {
        VaultGovernance.setOperator($, operator_);
    }

    /// @notice Owner, guardian or sentinel: removes the operator.
    function revokeOperator() external {
        VaultGovernance.revokeOperator($, guardian(), sentinel());
    }

    /// @notice Guardian only: ends the emergency once every redeemer has been paid in full (audit W-01b).
    function exitEmergency() external {
        VaultGovernance.exitEmergency($, guardian());
    }

    // ==================================================================
    // Switches and owner actions
    // ==================================================================
    function setDepositsPaused(bool paused) external {
        VaultGovernance.setDepositsPaused($, paused, guardian(), sentinel());
    }

    function setTradingPaused(bool paused) external {
        VaultGovernance.setTradingPaused($, paused, guardian(), sentinel());
    }

    function setDepositCap(uint256 cap) external {
        VaultGovernance.setDepositCap($, cap);
    }

    function lowerFees(uint16 mgmtBps, uint16 perfBps) external {
        VaultGovernance.lowerFees($, mgmtBps, perfBps);
    }

    /// @notice Recovers tokens sent here by mistake. Cannot touch the vault asset or its own shares.
    function rescueToken(IERC20 token, address to) external onlyOwner {
        if (address(token) == address($.asset) || address(token) == address(this)) revert UnsupportedAsset();
        token.safeTransfer(to, token.balanceOf(address(this)));
    }

    /// @dev A vault without an owner could never clear a breach or leave hosted (audit I-03).
    function renounceOwnership() public pure override {
        revert Unauthorized();
    }

    // ==================================================================
    // Timelock
    // ==================================================================
    function queue(bytes calldata data) external returns (bytes32) {
        return VaultGovernance.queue($, data);
    }

    function execute(bytes calldata data) external {
        VaultGovernance.execute($, data);
    }

    function cancel(bytes32 id) external {
        VaultGovernance.cancel($, id, guardian());
    }

    function setManager(address newManager) external onlySelf {
        VaultGovernance.setManager($, newManager);
    }

    function setFees(uint16 mgmtBps, uint16 perfBps) external onlySelf {
        VaultGovernance.setFees($, mgmtBps, perfBps);
    }

    function setFeeRecipient(address recipient) external onlySelf {
        VaultGovernance.setFeeRecipient($, recipient);
    }

    function setTimelockDelay(uint256 delay) external onlySelf {
        VaultGovernance.setTimelockDelay($, delay);
    }

    // ==================================================================
    // Storage getters
    // ==================================================================
    function policy() external view returns (VaultPolicy) {
        return $.policy;
    }

    function coreDepositWallet() external view returns (ICoreDepositWallet) {
        return $.coreDepositWallet;
    }

    function factory() external view returns (address) {
        return $.factory;
    }

    function protocolShareBps() external view returns (uint16) {
        return $.protocolShareBps;
    }

    function baseShareBps() external view returns (uint16) {
        return $.baseShareBps;
    }

    function hosted() external view returns (bool) {
        return $.hosted;
    }

    function manager() external view returns (address) {
        return $.manager;
    }

    function feeRecipient() external view returns (address) {
        return $.feeRecipient;
    }

    function agent() external view returns (address) {
        return $.agent;
    }

    function managementFeeBps() external view returns (uint16) {
        return $.managementFeeBps;
    }

    function performanceFeeBps() external view returns (uint16) {
        return $.performanceFeeBps;
    }

    /// @notice Performance fee rate that takes over at the next settle (0 = none scheduled).
    function pendingPerformanceFeeBps() external view returns (uint16) {
        return $.pendingPerformanceFeeBps;
    }

    function timelockDelay() external view returns (uint256) {
        return $.timelockDelay;
    }

    function depositCap() external view returns (uint256) {
        return $.depositCap;
    }

    function queuedEta(bytes32 id) external view returns (uint256) {
        return $.queuedEta[id];
    }

    function queuedAt(bytes32 id) external view returns (uint256) {
        return $.queuedAt[id];
    }

    function depositsPaused() external view returns (bool) {
        return $.depositsPaused;
    }

    function tradingPaused() external view returns (bool) {
        return $.tradingPaused;
    }

    function breached() external view returns (bool) {
        return $.breached;
    }

    function emergency() external view returns (bool) {
        return $.emergency;
    }

    function breachedAt() external view returns (uint64) {
        return $.breachedAt;
    }

    /// @notice Why the vault is in reduce only mode (BreachReason: 0 none, 1 leverage, 2 daily loss, 3 drawdown,
    ///         4 guardian, 5 emergency).
    function breachReason() external view returns (BreachReason) {
        return $.breachReason;
    }

    /// @notice True while a full stop imposed by the guardian or the sentinel freezes every settle (HLR2-E06). A full
    ///         stop imposed by the vault owner alone leaves this false and settles redemption-only.
    function platformHold() external view returns (bool) {
        return $.platformHold;
    }

    function operator() external view returns (address) {
        return $.operator;
    }

    /// @notice Insider deposits waiting for the next epoch's settlement.
    function deferredDepositAssets() external view returns (uint256) {
        return $.deferredDepositAssets;
    }

    /// @notice When the current emergency started (audit W-01b).
    function emergencyAt() external view returns (uint64) {
        return $.emergencyAt;
    }

    function currentEpoch() external view returns (uint256) {
        return $.currentEpoch;
    }

    function epochStartedAt() external view returns (uint64) {
        return $.epochStartedAt;
    }

    /// @notice This epoch's forced-exit deadline, fixed when it started (hl-r2 H01 / XB01).
    function epochDeadline() external view returns (uint64) {
        return $.epochDeadline;
    }

    function lastFeeAccrual() external view returns (uint64) {
        return $.lastFeeAccrual;
    }

    function pendingDepositAssets() external view returns (uint256) {
        return $.pendingDepositAssets;
    }

    function pendingRedeemShares() external view returns (uint256) {
        return $.pendingRedeemShares;
    }

    function claimableRedeemAssets() external view returns (uint256) {
        return $.claimableRedeemAssets;
    }

    function epochs(uint256 epoch)
        external
        view
        returns (
            uint256 depositAssets,
            uint256 depositShares,
            uint256 redeemShares,
            uint256 redeemAssets,
            uint256 redeemBurned,
            uint256 nav,
            uint256 sharePrice_,
            uint64 settledAt
        )
    {
        return (
            $.epochs[epoch].depositAssets,
            $.epochs[epoch].depositShares,
            $.epochs[epoch].redeemShares,
            $.epochs[epoch].redeemAssets,
            $.epochs[epoch].redeemBurned,
            $.epochs[epoch].nav,
            $.epochs[epoch].sharePrice,
            $.epochs[epoch].settledAt
        );
    }

    /// @notice Carry run of a redemption-only epoch: carriedFrom = origin + 1 (0 = not carried) and pricedIn = the
    ///         epoch that priced that run + 1 (0 = not yet).
    function carry(uint256 epoch) external view returns (uint256 carriedFrom, uint256 pricedIn) {
        carriedFrom = $.epochs[epoch].carriedFrom;
        if (carriedFrom != 0) pricedIn = $.carryPricedIn[carriedFrom - 1];
    }

    /// @notice When the owner last resumed trading after a drawdown breach (0 = never).
    function lastResumeAt() external view returns (uint64) {
        return $.lastResumeAt;
    }

    function RESUME_COOLDOWN() external pure returns (uint256) {
        return RESUME_COOLDOWN_;
    }

    function INSIDER_MIN_EPOCH_AGE() external pure returns (uint256) {
        return INSIDER_MIN_EPOCH_AGE_;
    }

    function requests(address controller) external view returns (uint256 epoch, uint256 depositAssets, uint256 redeemShares) {
        return ($.requests[controller].epoch, $.requests[controller].depositAssets, $.requests[controller].redeemShares);
    }

    function equityAtBridge() external view returns (uint256) {
        return $.equityAtBridge;
    }

    function bridgeAmount() external view returns (uint256) {
        return $.bridgeAmount;
    }

    function lastBridgeBlock() external view returns (uint256) {
        return $.lastBridgeBlock;
    }

    function highWaterMark() external view returns (uint256) {
        return $.highWaterMark;
    }

    function peakSharePrice() external view returns (uint256) {
        return $.peakSharePrice;
    }

    function riskDay() external view returns (uint256) {
        return $.riskDay;
    }

    /// @notice Share price at the first risk check of the UTC day: the daily loss reference.
    function dayStartSharePrice() external view returns (uint256) {
        return $.dayStartSharePrice;
    }

    function checkpointNav() external view returns (uint192) {
        return $.checkpointNav;
    }

    function checkpointAt() external view returns (uint64) {
        return $.checkpointAt;
    }

    /// @notice HLO-07: before this time a factory vault launched with an agent takes no deposit and the agent's
    ///         orders revert AgentWarmingUp (the platform's veto window). Zero for a vault launched without an agent.
    function agentActiveAt() external view returns (uint64) {
        return $.agentActiveAt;
    }

    /// @notice True while the checkpoint trails the NAV after a capped checkRisk step (HLR2-E01): an exit-only
    ///         settle waits for the next step instead of paying at it.
    function checkpointLagging() external view returns (bool) {
        return $.checkpointLagging;
    }

    // ------------------------------------------------------------------
    // Constants
    // ------------------------------------------------------------------
    function GRACE_PERIOD() external pure returns (uint256) {
        return GRACE_PERIOD_;
    }

    function BRIDGE_SETTLE_BLOCKS() external pure returns (uint256) {
        return BRIDGE_SETTLE_BLOCKS_;
    }

    function MIN_BRIDGE() external pure returns (uint256) {
        return MIN_BRIDGE_;
    }

    function MAX_BRIDGE_WAIT_BLOCKS() external pure returns (uint256) {
        return MAX_BRIDGE_WAIT_BLOCKS_;
    }

    function MAX_UNLANDED_BLOCKS() external pure returns (uint256) {
        return MAX_UNLANDED_BLOCKS_;
    }

    function MIN_DEPOSIT() external pure returns (uint256) {
        return MIN_DEPOSIT_;
    }

    function LEVERAGE_CLEAR_COOLDOWN() external pure returns (uint256) {
        return LEVERAGE_CLEAR_COOLDOWN_;
    }
}

src/HyperVaultFactory.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable2Step, Ownable} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {MessageHashUtils} from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

import {ICoreDepositWallet} from "./hypercore/HyperCore.sol";
import {HyperVault} from "./HyperVault.sol";
import {VaultPolicy} from "./VaultPolicy.sol";
import {InitParams, MIN_DEPOSIT as MIN_DEPOSIT_} from "./VaultTypes.sol";

/// @title HyperVaultFactory
/// @notice One transaction vault launch: clones a HyperVault and a VaultPolicy from fixed implementations,
///         initializes both, pulls the manager's USDC seed (EIP-2612 permit or prior approval), bridges it to
///         HyperCore to activate the vault's Core account and forwards HYPE for Core gas.
///
/// Platform controls (audit C-01, D-1, D-2, D-3, I-06, N-06, N-07, V-04):
///  - Only platform agents trade factory vaults. A launch carries the agent registrar's signature over
///    (agent, predicted vault, deadline); create() binds the agent to the vault it deploys and to nothing else, so
///    the registrar can no longer pre-bind a predicted address and block a creator's salt (V-04). A replacement
///    agent for an existing vault is registered by the registrar or the owner and set through the vault's
///    timelock; unregistering revokes the agent on its vault.
///  - Two rotatable platform roles that every factory vault reads live: the sentinel (hot, risk reducing
///    actions only) and the guardian (cold, breach clears and emergencies). The vault owner cannot replace them.
///  - Policies may only allowlist curated perps, and every factory vault has a deposit cap at or below the
///    platform maximum.
/// @dev Clones are EIP-1167 minimal proxies. The implementations are immutable here.
contract HyperVaultFactory is Ownable2Step {
    using SafeERC20 for IERC20;

    uint16 public constant BPS = 10_000;
    uint16 public constant MAX_PROTOCOL_SHARE_BPS = 5_000; // 50% of manager fees
    /// @notice Smallest deposit request on every vault (enforced by the vault, I3-07): 10 USDC.
    uint256 public constant MIN_DEPOSIT = MIN_DEPOSIT_;

    address public immutable vaultImplementation;
    address public immutable policyImplementation;
    IERC20 public immutable usdc;
    ICoreDepositWallet public immutable coreDepositWallet;

    // Config for FUTURE vaults. Existing vaults keep the share they were created with.
    address public protocolFeeRecipient;
    uint16 public baseShareBps = 1_000; // 10% of fees, own signals
    uint16 public hostedShareBps = 3_300; // 33% of fees, DojiPad hosted strategy
    uint256 public minSeedUsdc = 2e6; // 2 USDC (Core keeps 1 USDC as activation fee)
    uint256 public minHypeValue = 0.01 ether; // 0.01 HYPE for Core gas

    /// @notice Cold platform guardian: clears breaches, cancels queued items, triggers emergencies, unpauses.
    address public guardian;
    /// @notice Hot platform sentinel (the executor's monitor): revoke, pause, force reduce only, cancel orders.
    address public sentinel;
    /// @notice Wallet that registers platform agents before launches (the executor), separate from the owner.
    address public agentRegistrar;
    /// @notice Upper bound for every factory vault's depositCap.
    uint256 public maxDepositCap = 50_000e6;

    bool public openLaunch;
    mapping(address launcher => bool) public launcherAllowed;
    /// @notice The one vault a platform agent may be approved on (zero = not a platform agent).
    mapping(address agent => address vault) public platformAgentFor;
    /// @notice The agent bound to a vault address. One per predicted vault before launch (audit N2-04); an
    ///         existing vault may bind a replacement for a rotation through its timelock.
    mapping(address vault => address agent) public agentOfVault;
    mapping(uint32 asset => bool) public isAssetCurated;
    uint32[] internal _curated;

    address[] internal _vaults;
    mapping(address => bool) public isVault;
    mapping(address vault => address policy) public policyOf;

    struct CreateParams {
        string name;
        string symbol;
        address owner;
        address manager;
        address feeRecipient;
        uint16 managementFeeBps;
        uint16 performanceFeeBps;
        uint256 timelockDelay;
        uint256 depositCap;
        VaultPolicy.RiskConfig risk;
        uint32[] assets;
        address agent; // zero for manual mode, otherwise a platform agent signed for this launch by the registrar
        bytes agentSig; // registrar signature over agentDigest(agent, predicted vault, agentDeadline)
        uint256 agentDeadline;
        address operator; // treasury operator (the platform keeper by default), zero for none
        bool hosted;
        uint256 seedUsdc; // >= minSeedUsdc, pulled from msg.sender
        bytes32 salt;
    }

    /// @dev EIP-2612 permit for `usdc` with spender = this factory. deadline == 0 skips the permit and relies on
    ///      an existing allowance (the fallback approve path).
    struct PermitData {
        uint256 value;
        uint256 deadline;
        uint8 v;
        bytes32 r;
        bytes32 s;
    }

    event VaultCreated(
        address indexed vault,
        address indexed policy,
        address indexed owner,
        address manager,
        address agent,
        bool hosted,
        uint16 protocolShareBps,
        bytes32 salt
    );
    event ProtocolFeeRecipientUpdated(address recipient);
    event SharesUpdated(uint16 baseShareBps, uint16 hostedShareBps);
    event ProtocolShareLowered(address indexed vault, uint16 shareBps);
    event MinSeedUpdated(uint256 minSeedUsdc);
    event MinHypeUpdated(uint256 minHypeValue);
    event LauncherAllowed(address indexed launcher, bool allowed);
    event OpenLaunchSet(bool open);
    event GuardianUpdated(address guardian);
    event SentinelUpdated(address sentinel);
    event AgentRegistrarUpdated(address registrar);
    event PlatformAgentRegistered(address indexed agent, address indexed vault, bool registered);
    event AssetCurated(uint32 indexed asset, bool curated);
    event MaxDepositCapUpdated(uint256 cap);

    error LaunchClosed();
    error InvalidShare();
    error SeedTooSmall(uint256 sent, uint256 min);
    error HypeTooSmall(uint256 sent, uint256 min);
    error NotAVault();
    error ZeroAddress();
    error NotPlatformAgent(address agent);
    error AssetNotCurated(uint32 asset);
    error CapAboveMax(uint256 cap, uint256 max);
    error NotRegistrar();
    error AgentAlreadyBound(address agent, address vault);
    error VaultAlreadyHasAgent(address vault, address agent);
    error LiveAgent(address agent, address vault);
    error RolesCollide();
    error BadAgentSignature();

    constructor(
        address owner_,
        address vaultImplementation_,
        address policyImplementation_,
        IERC20 usdc_,
        ICoreDepositWallet coreDepositWallet_,
        address protocolFeeRecipient_,
        address guardian_,
        address sentinel_
    ) Ownable(owner_) {
        if (
            vaultImplementation_ == address(0) || policyImplementation_ == address(0) || address(usdc_) == address(0)
                || address(coreDepositWallet_) == address(0) || protocolFeeRecipient_ == address(0) || guardian_ == address(0)
                || sentinel_ == address(0)
        ) revert ZeroAddress();
        _checkRoles(owner_, guardian_, sentinel_, address(0));
        vaultImplementation = vaultImplementation_;
        policyImplementation = policyImplementation_;
        usdc = usdc_;
        coreDepositWallet = coreDepositWallet_;
        protocolFeeRecipient = protocolFeeRecipient_;
        guardian = guardian_;
        sentinel = sentinel_;
    }

    /// @notice True when `agent` is bound to some vault (registered and not yet unregistered).
    function isPlatformAgent(address agent) external view returns (bool) {
        return platformAgentFor[agent] != address(0);
    }

    // ------------------------------------------------------------------
    // Views
    // ------------------------------------------------------------------
    function vaults() external view returns (address[] memory) {
        return _vaults;
    }

    function vaultCount() external view returns (uint256) {
        return _vaults.length;
    }

    /// @notice Curated perp indices (those currently enabled).
    function curatedAssets() external view returns (uint32[] memory out) {
        uint256 n;
        for (uint256 i; i < _curated.length; ++i) {
            if (isAssetCurated[_curated[i]]) ++n;
        }
        out = new uint32[](n);
        n = 0;
        for (uint256 i; i < _curated.length; ++i) {
            if (isAssetCurated[_curated[i]]) out[n++] = _curated[i];
        }
    }

    /// @notice Address a `create` by `creator` with `salt` will deploy to. Salts are scoped per creator.
    function predictVaultAddress(address creator, bytes32 salt) public view returns (address) {
        return Clones.predictDeterministicAddress(vaultImplementation, _scopedSalt(creator, salt), address(this));
    }

    function canLaunch(address launcher) public view returns (bool) {
        return openLaunch || launcherAllowed[launcher];
    }

    /// @notice What the agent registrar signs (EIP-191 personal message of this hash) to let `vault` launch with
    ///         `agent`: bound to this chain, this factory, the agent, the predicted vault and a deadline.
    function agentDigest(address agent, address vault, uint256 deadline) public view returns (bytes32) {
        return keccak256(abi.encode("DojiPad platform agent", block.chainid, address(this), agent, vault, deadline));
    }

    // ------------------------------------------------------------------
    // Launch
    // ------------------------------------------------------------------
    /// @notice Deploys and activates a vault in one transaction.
    /// @param p vault, policy, agent and seed configuration. The guardian and sentinel are the platform's.
    /// @param permit USDC permit for at least p.seedUsdc with this factory as spender; deadline 0 = use allowance
    /// @dev msg.value (>= minHypeValue) is forwarded through the vault to its HyperCore spot balance as HYPE.
    function create(CreateParams calldata p, PermitData calldata permit)
        external
        payable
        returns (address vault, address policy)
    {
        if (!canLaunch(msg.sender)) revert LaunchClosed();
        if (guardian == sentinel) revert RolesCollide();
        if (p.seedUsdc < minSeedUsdc) revert SeedTooSmall(p.seedUsdc, minSeedUsdc);
        if (msg.value < minHypeValue) revert HypeTooSmall(msg.value, minHypeValue);
        if (p.agent != address(0) && platformAgentFor[p.agent] != predictVaultAddress(msg.sender, p.salt)) {
            // Not pre-bound by the (cold) owner: the registrar's signature for exactly this launch binds it now.
            if (p.agentSig.length == 0) revert NotPlatformAgent(p.agent);
            address predicted = predictVaultAddress(msg.sender, p.salt);
            if (platformAgentFor[p.agent] != address(0)) revert AgentAlreadyBound(p.agent, platformAgentFor[p.agent]);
            if (agentOfVault[predicted] != address(0)) revert VaultAlreadyHasAgent(predicted, agentOfVault[predicted]);
            if (block.timestamp > p.agentDeadline) revert BadAgentSignature();
            address signer = ECDSA.recover(MessageHashUtils.toEthSignedMessageHash(agentDigest(p.agent, predicted, p.agentDeadline)), p.agentSig);
            if (signer == address(0) || (signer != agentRegistrar && signer != owner())) revert BadAgentSignature();
            platformAgentFor[p.agent] = predicted;
            agentOfVault[predicted] = p.agent;
            emit PlatformAgentRegistered(p.agent, predicted, true);
        }
        if (p.depositCap == 0 || p.depositCap > maxDepositCap) revert CapAboveMax(p.depositCap, maxDepositCap);
        for (uint256 i; i < p.assets.length; ++i) {
            if (!isAssetCurated[p.assets[i]]) revert AssetNotCurated(p.assets[i]);
        }

        if (permit.deadline != 0) {
            // A front run permit with the same signature would already have set the allowance; never let
            // that brick the launch, the transferFrom below is the real check.
            try IERC20Permit(address(usdc)).permit(
                msg.sender, address(this), permit.value, permit.deadline, permit.v, permit.r, permit.s
            ) {} catch {}
        }

        vault = Clones.cloneDeterministic(vaultImplementation, _scopedSalt(msg.sender, p.salt));
        policy = Clones.clone(policyImplementation);
        VaultPolicy(policy).initialize(p.owner, p.risk, p.assets, p.timelockDelay, address(this));

        // Seed goes straight to the vault; initialize bridges it to Core spot.
        usdc.safeTransferFrom(msg.sender, vault, p.seedUsdc);

        uint16 share = p.hosted ? hostedShareBps : baseShareBps;
        HyperVault(vault).initialize{value: msg.value}(
            InitParams({
                asset: usdc,
                name: p.name,
                symbol: p.symbol,
                owner: p.owner,
                manager: p.manager,
                guardian: address(0),
                feeRecipient: p.feeRecipient,
                managementFeeBps: p.managementFeeBps,
                performanceFeeBps: p.performanceFeeBps,
                timelockDelay: p.timelockDelay,
                depositCap: p.depositCap,
                policy: VaultPolicy(policy),
                coreDepositWallet: coreDepositWallet,
                factory: address(this),
                protocolShareBps: share,
                baseShareBps: baseShareBps,
                hosted: p.hosted,
                agent: p.agent,
                operator: p.operator,
                seedUsdc: p.seedUsdc
            })
        );

        _vaults.push(vault);
        isVault[vault] = true;
        policyOf[vault] = policy;
        emit VaultCreated(vault, policy, p.owner, p.manager, p.agent, p.hosted, share, p.salt);
    }

    // ------------------------------------------------------------------
    // Platform agents. An agent is bound to exactly one vault, for good (audit N-07). New vaults bind theirs in
    // create() from the registrar's signature. Here: the registrar or the owner registers a replacement agent for
    // an EXISTING vault (set on the vault through its timelock); only the cold owner may still pre-bind a predicted
    // address. The hot registrar key can no longer bind a predicted vault and block a creator's salt (V-04).
    // ------------------------------------------------------------------
    function registerPlatformAgent(address agent, address vault) external {
        if (msg.sender != agentRegistrar && msg.sender != owner()) revert NotRegistrar();
        if (agent == address(0) || vault == address(0)) revert ZeroAddress();
        if (!isVault[vault] && msg.sender != owner()) revert NotRegistrar();
        if (platformAgentFor[agent] != address(0)) revert AgentAlreadyBound(agent, platformAgentFor[agent]);
        if (agentOfVault[vault] != address(0) && !isVault[vault]) revert VaultAlreadyHasAgent(vault, agentOfVault[vault]);
        platformAgentFor[agent] = vault;
        agentOfVault[vault] = agent;
        emit PlatformAgentRegistered(agent, vault, true);
    }

    /// @notice Marks the agent unusable. An agent that is live on its vault is also revoked there, which only the
    ///         owner, the guardian or the sentinel may trigger: the registrar alone cannot stop a vault (audit I2-03).
    function unregisterPlatformAgent(address agent) external {
        bool platformRole = msg.sender == owner() || msg.sender == guardian || msg.sender == sentinel;
        if (msg.sender != agentRegistrar && !platformRole) revert NotRegistrar();
        address vault = platformAgentFor[agent];
        if (vault == address(0)) return;
        if (isVault[vault] && HyperVault(vault).agent() == agent) {
            if (!platformRole) revert LiveAgent(agent, vault);
            HyperVault(vault).revokeAgent();
        }
        delete platformAgentFor[agent];
        if (agentOfVault[vault] == agent) delete agentOfVault[vault];
        emit PlatformAgentRegistered(agent, vault, false);
    }

    // ------------------------------------------------------------------
    // Owner config (future vaults only, except lowerProtocolShare)
    // ------------------------------------------------------------------
    function setProtocolFeeRecipient(address recipient) external onlyOwner {
        if (recipient == address(0)) revert ZeroAddress();
        protocolFeeRecipient = recipient;
        emit ProtocolFeeRecipientUpdated(recipient);
    }

    function setShares(uint16 baseShareBps_, uint16 hostedShareBps_) external onlyOwner {
        if (baseShareBps_ > MAX_PROTOCOL_SHARE_BPS || hostedShareBps_ > MAX_PROTOCOL_SHARE_BPS) revert InvalidShare();
        baseShareBps = baseShareBps_;
        hostedShareBps = hostedShareBps_;
        emit SharesUpdated(baseShareBps_, hostedShareBps_);
    }

    /// @notice Lowers one existing vault's locked protocol share. The vault rejects anything that is not lower.
    function lowerProtocolShare(address vault, uint16 newBps) external onlyOwner {
        if (!isVault[vault]) revert NotAVault();
        HyperVault(vault).lowerProtocolShare(newBps);
        emit ProtocolShareLowered(vault, newBps);
    }

    function setMinSeedUsdc(uint256 amount) external onlyOwner {
        minSeedUsdc = amount;
        emit MinSeedUpdated(amount);
    }

    function setMinHypeValue(uint256 amount) external onlyOwner {
        minHypeValue = amount;
        emit MinHypeUpdated(amount);
    }

    function setLauncherAllowed(address launcher, bool allowed) external onlyOwner {
        launcherAllowed[launcher] = allowed;
        emit LauncherAllowed(launcher, allowed);
    }

    function setOpenLaunch(bool open) external onlyOwner {
        openLaunch = open;
        emit OpenLaunchSet(open);
    }

    /// @notice Rotates the cold guardian for every factory vault at once (vaults read it live).
    function setGuardian(address guardian_) external onlyOwner {
        if (guardian_ == address(0)) revert ZeroAddress();
        _checkRoles(owner(), guardian_, sentinel, agentRegistrar);
        _checkRoles(pendingOwner(), guardian_, sentinel, agentRegistrar);
        guardian = guardian_;
        emit GuardianUpdated(guardian_);
    }

    /// @notice Rotates the hot sentinel for every factory vault at once (vaults read it live).
    function setSentinel(address sentinel_) external onlyOwner {
        if (sentinel_ == address(0)) revert ZeroAddress();
        _checkRoles(owner(), guardian, sentinel_, agentRegistrar);
        _checkRoles(pendingOwner(), guardian, sentinel_, agentRegistrar);
        sentinel = sentinel_;
        emit SentinelUpdated(sentinel_);
    }

    function setAgentRegistrar(address registrar) external onlyOwner {
        _checkRoles(owner(), guardian, sentinel, registrar);
        _checkRoles(pendingOwner(), guardian, sentinel, registrar);
        agentRegistrar = registrar;
        emit AgentRegistrarUpdated(registrar);
    }

    /// @dev Two step, and the incoming owner may not be one of the hot roles. Owner == guardian is allowed: one
    ///      cold multisig may hold both (audit I2-05 / I2-06).
    function transferOwnership(address newOwner) public override onlyOwner {
        _checkRoles(newOwner, guardian, sentinel, agentRegistrar);
        super.transferOwnership(newOwner);
    }

    /// @dev A factory without an owner could never rotate a role again (audit V-03).
    function renounceOwnership() public view override onlyOwner {
        revert RolesCollide();
    }

    function setAssetCurated(uint32 asset, bool curated) external onlyOwner {
        if (!isAssetCurated[asset] && curated) {
            bool listed;
            for (uint256 i; i < _curated.length; ++i) {
                if (_curated[i] == asset) listed = true;
            }
            if (!listed) _curated.push(asset);
        }
        isAssetCurated[asset] = curated;
        emit AssetCurated(asset, curated);
    }

    function setMaxDepositCap(uint256 cap) external onlyOwner {
        maxDepositCap = cap;
        emit MaxDepositCapUpdated(cap);
    }

    // ------------------------------------------------------------------
    // Internal
    // ------------------------------------------------------------------
    function _scopedSalt(address creator, bytes32 salt) internal pure returns (bytes32) {
        return keccak256(abi.encode(creator, salt));
    }

    /// @dev The hot roles (sentinel, registrar) are distinct from each other and from the cold ones (owner,
    ///      guardian); guardian != sentinel always. A zero registrar means none (audit I2-05). The setters run the
    ///      check against the pending owner too, so an accepted transfer never creates a collision (audit V-03);
    ///      a zero pending owner is skipped.
    function _checkRoles(address owner_, address guardian_, address sentinel_, address registrar_) internal pure {
        if (owner_ == address(0)) {
            if (guardian_ == sentinel_) revert RolesCollide();
            if (registrar_ != address(0) && (registrar_ == guardian_ || registrar_ == sentinel_)) revert RolesCollide();
            return;
        }
        if (guardian_ == sentinel_ || sentinel_ == owner_) revert RolesCollide();
        if (registrar_ != address(0) && (registrar_ == owner_ || registrar_ == guardian_ || registrar_ == sentinel_)) {
            revert RolesCollide();
        }
    }
}

